import { expect, it } from 'vitest';
import { proteinChargeAtPh, proteinIsoelectricPoint } from '../../src/seq/stats';

it('pI is a root of the charge model, not clamped at 4.05', () => {
  const FLAG = 'DYKDDDDK'; // ExPASy Compute pI/Mw: 3.97
  const PTMA = 'MSDAAVDTSSEITTKDLKEKKEVVEEAENGRDAPANGNAENEENGEQEADNEVDEEEEEGGEEEEEEEEGDGEEEDGDEDEEAESATGKRAAEDDEDDDVDTKKQKTDEDD'; // P06454, ExPASy ProtParam: 3.66
  for (const p of [FLAG, PTMA]) {
    const pI = proteinIsoelectricPoint(p); // 4.0500284194946286 for both
    expect(Math.abs(proteinChargeAtPh(p, pI))).toBeLessThan(0.01); // received 0.260 (FLAG), 8.708 (PTMA)
  }
  expect(proteinIsoelectricPoint(FLAG)).toBeCloseTo(3.97, 2);
  expect(proteinIsoelectricPoint(PTMA)).toBeCloseTo(3.69, 1);
});

