describe('seqtools science review', () => {
  it('proteinIsoelectricPoint equals Biopython isoelectric_point() within 0.01', () => {
    // tools/oracle/.venv/bin/python -I -c "from Bio.SeqUtils.ProtParam import ProteinAnalysis as PA; print(PA('DL').isoelectric_point())"
    const biopython: Record<string, number> = {
      DL: 4.0500284194946286, EA: 4.0500284194946286, DYKDDDDK: 4.0500284194946286,
      EWGVFWYTWWDTFEWIFYED: 4.0500284194946286, RKKHR: 11.999967765808105,
    };
    for (const [p, pi] of Object.entries(biopython)) expect(Math.abs(proteinIsoelectricPoint(p) - pi), p).toBeLessThan(0.01);
  });
});
